/**
 * Attribute emission fixtures.
 *
 * Nothing here is called by the integration tests: this module exists so that every
 * shape the code generators have to render for an attribute appears in checked-in
 * generated output, where a regression is a diff rather than a silent behaviour change.
 *
 * Two families are covered.
 *
 * * A **user declared** attribute, `@Cache`, with one parameter of each kind the
 *   attribute binder can produce — an integer, a string, a bool, an array, and a
 *   trailing optional — used with the optional written and with it omitted. Only C#
 *   has a general purpose annotation mechanism, so `@Cache` is expected to appear in
 *   the C# output alone.
 * * **`@deprecated`**, in all four argument shapes (none, `since` only, `reason` only,
 *   both), on a msg, a field, an enum, an enum member, a service and a method. This one
 *   is expected in every target, each in its own idiom: `[Obsolete]`, a `@deprecated`
 *   JSDoc tag, `#[deprecated]`, and a `// Deprecated:` doc paragraph.
 */
/**
 * Deprecated service, to pin the marker on a service as well as on its methods.
 *
 * @deprecated since 0.6: use CacheInteraction
 */
export interface ILegacyCacheInteraction extends IIonService
{
  /**
   * Nothing here is reachable; the service exists for its `@deprecated`.
   */
  Ping(): Promise<i4>;
}


/**
 * Cache control surface.
 */
export interface ICacheInteraction extends IIonService
{
  /**
   * `@deprecated` with both arguments, on a method.
   *
   * @deprecated since 0.6: use Current instead
   */
  Legacy(id: i4): Promise<i4>;
  /**
   * `@deprecated` with only `reason`, written as a named argument — which the binder
   * normalizes into `[null, "…"]`, i.e. a null in a *leading* slot that must survive.
   *
   * @deprecated renamed to Current
   */
  Renamed(id: i4): Promise<i4>;
  /**
   * `@deprecated` with no arguments, on a method.
   *
   * @deprecated
   */
  Bare(id: i4): Promise<i4>;
  /**
   * A std attribute with a real C# counterpart beside a user declared one. `@deadline`
   * is the case that used to emit `[deadline(30)]` and fail to resolve against
   * `ion.runtime.DeadlineAttribute`.
   */
  Current(id: i4): Promise<i4>;
  /**
   * A parameterless user attribute, and a std marker with no target-language form.
   */
  Ping(): Promise<i4>;
}




/**
 * `Map<K,V>`, `Set<T>` and the fixed-size array `T[N]` contracts.
 *
 * One file per shape would hide the interesting half. What has to hold here is that the
 * three containers behave like every other Ion type in *every* position a generator has
 * to spell — a message field, a method argument, a method return — and that they still
 * behave when stacked with the modifiers (`?`, `[]`, `~`) and with each other.
 *
 * What each container buys, and therefore what the integration tests assert:
 *
 * * `Map<K,V>` is a definite-length CBOR map whose keys are sorted in canonical
 *   RFC 8949 §4.2.1 order — byte length first, then lexicographically. The sort is the
 *   whole feature: a C# `Dictionary`, a JavaScript `Map` and a Rust `HashMap` have three
 *   different iteration orders, so without a total order the same logical map would
 *   produce three different byte strings.
 * * `Set<T>` is CBOR tag 258 wrapping a definite-length array, elements under the same
 *   ordering. The tag is what tells it apart from `Array<T>` on the wire; without it a
 *   captured payload would be ambiguous to anything that does not already hold the schema.
 * * `T[N]` is a definite-length array of exactly N, and a wrong length is a typed decode
 *   error naming both lengths — not a truncation, and not a silent pad.
 */
/**
 * Round-trip surface: each container in argument and in return position.
 *
 * Return position is where the three targets diverge most. C# has no
 * `CallAsyncWithFixedArray`, so the generated client checks `T[N]`'s length itself with the
 * runtime's own typed exception; TypeScript registers the whole fixed array under one
 * formatter name (`f4[16]`) and lets the ordinary nullable/plain call resolve it; Rust's
 * `[T; N]` needs nothing at all, because the const-generic `IonFormat` impl carries N.
 */
export interface ICollectionInteraction extends IIonService
{
  /**
   * `Map<K,V>` in and out. The integration test sends the same entries in two different
   * insertion orders and asserts identical request bytes.
   */
  CountByTag(tags: Map<string, i4>): Promise<Map<string, i4>>;
  /**
   * `Set<T>` in and out — same insertion-order claim, plus tag 258 on the wire.
   */
  Dedup(ids: Set<i4>): Promise<Set<i4>>;
  /**
   * `T[N]` in and out. A wrong length must be a typed error at both ends.
   */
  Rotate(coords: IonArray<f4>): Promise<IonArray<f4>>;
  /**
   * `T[N]?` in and out. A null argument returns null, so the null branch is reachable.
   */
  RotateMaybe(coords: IonArray<f4> | null): Promise<IonArray<f4> | null>;
  /**
   * `Map<K,V>?` in and out, with a message value.
   */
  Lookup(members: Map<string, Member> | null): Promise<Map<string, Member> | null>;
  /**
   * `Set<T>[]` in and out.
   */
  Regroup(groups: IonArray<Set<i4>>): Promise<IonArray<Set<i4>>>;
  /**
   * `Map<K, T~>` in and out.
   */
  Patch(patches: Map<string, IonPartial<Doc>>): Promise<Map<string, IonPartial<Doc>>>;
  /**
   * `Map<K, T[]>` in and out — the nested-array adapter over a real transport.
   */
  Roster(rosters: Map<string, IonArray<Member>>): Promise<Map<string, IonArray<Member>>>;
  /**
   * A container beside a plain argument, to pin the argument count: a write path that
   * emits nothing for a container while still declaring the full array length produces
   * malformed CBOR rather than a compile error.
   */
  Merge(baseline: Map<string, i4>, weight: i4): Promise<Map<string, i4>>;
  /**
   * Every field shape in one message, over a real transport.
   */
  Echo(shapes: ContainerShapes): Promise<ContainerShapes>;
  /**
   * Every legal key type in one message, over a real transport.
   */
  EchoKeys(keys: KeyMatrix): Promise<KeyMatrix>;
}




/**
 * Binary payload round-trip contracts.
 *
 * These services exist to exercise the `bytes` primitive across every method
 * shape the runtime supports: void return, single round-trip, and repeated
 * round-trips over the same connection.
 */
/**
 * Blob echo service used by the transport tests.
 *
 * Nothing here interprets the payload; the methods only prove that a byte
 * buffer survives serialization, transport and deserialization unchanged.
 */
export interface ITestBlobs extends IIonService
{
  /**
   * Accepts a payload and returns nothing. Exercises the void-return path.
   */
  Do(data: bytes): Promise<void>;
  /**
   * Echoes the payload back to the caller.
   */
  DoIt(data: bytes): Promise<bytes>;
  /**
   * Second echo overload. The duplicate methods let the tests issue several
   * distinct calls over one connection without reusing a method name.
   */
  DoIt2(data: bytes): Promise<bytes>;
  /**
   * Third echo overload. See DoIt2.
   */
  DoIt3(data: bytes): Promise<bytes>;
}




/**
 * Ion names that collide with a target language's reserved words.
 *
 * An Ion identifier is constrained by Ion's grammar and by nothing else, so a field
 * spelled `fixed:`, `type:` or `class:` is legal here and used to emit C#, Rust and
 * TypeScript that did not parse. Every declaration position a generator writes an Ion
 * name into is represented below, with names drawn from all three keyword sets at once:
 *
 * * C# escapes with `@` — `@fixed`, `@class`, `@int`, `@event`, `@lock`, `@default`.
 * * Rust escapes with `r#` — `r#type`, `r#move`, `r#match`, `r#fn`, `r#static`.
 * * TypeScript has no escape, so a *binding* position (a parameter, a `const`, an
 *   object-literal shorthand) is renamed to `__class` / `__function` / `__default`,
 *   while property names, enum members and member accesses keep the Ion spelling —
 *   `interface M { class: string }` is valid TypeScript, `function f(class)` is not.
 *
 * **None of it may reach the wire.** A message is encoded positionally, so a field name
 * is a declaration and nothing else; a `Partial<T>` is keyed *by field name*, and
 * `ion.lock.json` records the Ion spelling. Both must read back exactly as written here.
 */
/**
 * Keyword names in method and argument position.
 */
export interface IKeywordInteraction extends IIonService
{
  /**
   * Reserved words as method *parameters*: a C# parameter, a Rust `async fn` argument
   * and — the one that actually fails without a rename — a TypeScript parameter.
   */
  Echo(__class: string, type: i4, __default: bool): Promise<string>;
  /**
   * A reserved word as the *method* name. The router still dispatches on the Ion
   * spelling: the generated `methodName.Equals("lock", …)` is a string, not an
   * identifier, and `nameof(@lock)` is `"lock"`.
   */
  lock(value: i4): Promise<i4>;
  /**
   * The whole message over a real signature.
   */
  Roundtrip(fields: KeywordFields): Promise<KeywordFields>;
  /**
   * A patch in argument and return position, so the field-name keys are exercised
   * end to end.
   */
  Patch(patch: IonPartial<KeywordPatchTarget>): Promise<IonPartial<KeywordPatchTarget>>;
  /**
   * The union in both positions.
   */
  Pick(choice: IKeywordUnion): Promise<IKeywordUnion>;
}




/**
 * `datetime` and `decimal` contracts.
 *
 * Both primitives exist for one reason — not silently rounding a value off — so both are
 * exercised here in every position a generator has to spell: bare, optional, array,
 * optional array, as a typedef target, inside a `Partial<T>` target, and in a service
 * signature (argument, return, and the service level bound operand).
 *
 * * `datetime` is CBOR tag 0 + RFC 3339 text, always with an explicit numeric offset and
 *   always with exactly seven fractional digits. It maps to `System.DateTimeOffset`,
 *   `IonDateTime` and `chrono::DateTime<chrono::FixedOffset>` — never to `System.DateTime`,
 *   which has no offset field and decodes `-05:00` back as UTC, and never to a JavaScript
 *   `Date`, which is millisecond resolution and cannot hold a 100ns tick.
 * * `decimal` is CBOR tag 4, `[exponent, mantissa]`. It maps to `System.Decimal`,
 *   `IonDecimal` and `ion_rustcore::IonDecimal` — never to `f8`, which cannot represent
 *   `0.1` at all.
 *
 * The integration tests round-trip a non-UTC offset, a sub-millisecond tick and a decimal
 * that `double` cannot hold, because those are the three values that tell a correct
 * mapping apart from one that merely compiles.
 */
/**
 * Round-trip surface for `datetime` and `decimal`.
 *
 * The service level operand is itself a `datetime`, so every generated method signature
 * carries one — that is the position that would have gone unnoticed if only fields were
 * covered.
 */
export interface ILedgerInteraction extends IIonService
{
  /**
   * `datetime` in both argument and return position. The one method whose result proves
   * the offset and the sub-millisecond tick survived the wire.
   */
  Echo(openedAt: datetime, at: datetime): Promise<datetime>;
  /**
   * `decimal` in both argument and return position.
   */
  EchoAmount(openedAt: datetime, amount: decimal): Promise<decimal>;
  /**
   * The whole message, so every field shape above goes over a real transport.
   */
  Roundtrip(openedAt: datetime, entry: LedgerEntry): Promise<LedgerEntry>;
  /**
   * Optional in argument and return position: `Maybe<datetime>` / `Maybe<decimal>`.
   * A null `amount` returns null, so the null branch is reachable.
   */
  EchoMaybe(openedAt: datetime, at: datetime | null, amount: decimal | null): Promise<decimal | null>;
  /**
   * Arrays of both, with an array return.
   */
  EchoMany(openedAt: datetime, instants: IonArray<datetime>, amounts: IonArray<decimal>): Promise<IonArray<datetime>>;
  /**
   * A `Partial<T>` whose target is made of the new primitives, in both positions.
   */
  Patch(openedAt: datetime, patch: IonPartial<LedgerPatch>): Promise<IonPartial<LedgerPatch>>;
}




/**
 * Arithmetic RPC surface used by the IonPath integration tests.
 *
 * Every service in this module is stateless: the left-hand operand is bound
 * once, as a service argument, and reused by every method call on that client.
 */
/**
 * Integer arithmetic over a fixed left-hand operand.
 *
 * The operand is supplied when the client is constructed, so calling Add(2)
 * on a client created with leftOperand = 40 yields 42.
 */
export interface IMathInteraction extends IIonService
{
  /**
   * Adds rightOperand to the bound operand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Add(leftOperand: i4, rightOperand: i4): Promise<i4>;
  /**
   * Multiplies the bound operand by rightOperand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Mul(leftOperand: i4, rightOperand: i4): Promise<i4>;
  /**
   * Subtracts rightOperand from the bound operand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Sub(leftOperand: i4, rightOperand: i4): Promise<i4>;
  /**
   * Divides the bound operand by rightOperand.
   *
   * Division by zero surfaces as an RPC fault, not as a return value.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Div(leftOperand: i4, rightOperand: i4): Promise<i4>;
  /**
   * Raises the bound operand to the power of rightOperand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Pow(leftOperand: i4, rightOperand: i4): Promise<i4>;
  /**
   * Raises the bound operand to each power in rightOperand, elementwise.
   *
   * The result array has the same length as the input array.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  PowArray(leftOperand: i4, rightOperand: IonArray<i4>): Promise<IonArray<i4>>;
  /**
   * Returns the absolute value of rightOperand, or null when it is null.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  ToPositive(leftOperand: i4, rightOperand: i4 | null): Promise<i4 | null>;
  /**
   * `i4[]?` in both argument and return position: null in, null out; otherwise the
   * elementwise power, same length as the input.
   *
   * The return is the shape the C# client used to emit `CallAsyncNullable<Array>` for —
   * `Maybe<Array<i4>>` collapsed to the bare word `Array` instead of naming the element
   * type. A value-typed element is the interesting half: `IonArray<i4>?` is a nullable
   * struct, so a reader that peels only one wrapper cannot even be coerced into compiling.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  PowArrayMaybe(leftOperand: i4, rightOperand: IonArray<i4> | null): Promise<IonArray<i4> | null>;
  /**
   * The same return shape over a reference-typed element, to pin that the fix is not
   * specific to value types.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  Spell(leftOperand: i4, rightOperand: IonArray<i4> | null): Promise<IonArray<string> | null>;
}


/**
 * Deterministic pseudo-random streams seeded by the caller.
 */
export interface IRandomStreamInteraction extends IIonService
{
  /**
   * Streams i pseudo-random integers derived from the seed.
   *
   * @param seed Seed for the underlying generator. The same seed always yields the
   *   same sequence, which is what makes the streaming tests reproducible.
   */
  Integer(seed: i4, i: i4): AsyncIterable<i4>;
  /**
   * Bidirectional stream: every f4 pushed by the client is answered with a
   * pseudo-random f4 derived from the seed and that input.
   *
   * @param seed Seed for the underlying generator. The same seed always yields the
   *   same sequence, which is what makes the streaming tests reproducible.
   */
  Floats(seed: i4, i: AsyncIterable<f4>): AsyncIterable<f4>;
}




/**
 * `Partial<T>` ("T~") contracts.
 *
 * Exercises every shape the generators have to emit for a partial: as a message
 * field, as a method argument, as a method return, and under each of the four
 * modifier stackings (`T~`, `T~[]`, `T~?`, `T~[]?`).
 */
/**
 * Patch application over the wire.
 */
export interface IPatchInteraction extends IIonService
{
  /**
   * A patch in both argument and return position.
   */
  Apply(patch: IonPartial<PatchTarget>): Promise<IonPartial<PatchTarget>>;
  /**
   * An array of patches in, an optional patch out.
   */
  ApplyMany(patches: IonArray<IonPartial<PatchTarget>>): Promise<IonPartial<PatchTarget> | null>;
  /**
   * `T~[]` in return position — `Array<Partial<PatchTarget>>`.
   */
  ApplyAll(patches: IonArray<IonPartial<PatchTarget>>): Promise<IonArray<IonPartial<PatchTarget>>>;
  /**
   * `T~[]?` in return position — `Maybe<Array<Partial<PatchTarget>>>`, the two collapsing
   * wrappers stacked. An empty input returns null so the null branch is reachable.
   */
  ApplySome(patches: IonArray<IonPartial<PatchTarget>>): Promise<IonArray<IonPartial<PatchTarget>> | null>;
  /**
   * A patch beside a plain argument, to pin the argument count: the write path used
   * to emit nothing for a partial while still declaring the full array length.
   */
  ApplyTo(target: PatchTarget, patch: IonPartial<PatchTarget>): Promise<PatchTarget>;
  /**
   * Messages whose own fields are patches.
   */
  Rewrap(envelope: PatchEnvelope): Promise<PatchEnvelope>;
}




/**
 * Streaming surface for the stream lifecycle, transport and resilience tests.
 *
 * Each method exists to put the server in one particular state: completing, failing, never
 * yielding on its own, echoing input, ignoring its cancellation token, or pushing large frames.
 */
/**
 * The streams the stream tests drive.
 */
export interface IStreamLab extends IIonService
{
  /**
   * `count` consecutive integers starting at `from`, `delayMs` apart.
   */
  Count(from: i4, count: i4, delayMs: i4): AsyncIterable<i4>;
  /**
   * Yields nothing itself: joins the group `topic` and receives everything by push.
   */
  Listen(topic: string): AsyncIterable<LabEvent>;
  /**
   * Push-only stream of a union element; joins the group `room:{room}`.
   */
  Signals(room: string): AsyncIterable<ILabSignal>;
  /**
   * Every input item back, upper-cased, in order.
   */
  Echo(input: AsyncIterable<string>): AsyncIterable<string>;
  /**
   * `after` items, then an exception.
   */
  Explode(after: i4): AsyncIterable<i4>;
  /**
   * One item, then ignores its cancellation token for `holdMs` before finishing.
   */
  Stubborn(holdMs: i4): AsyncIterable<i4>;
  /**
   * `count` payloads of `size` bytes each; byte i of payload n is (n + i) mod 251.
   */
  Blobs(size: i4, count: i4): AsyncIterable<bytes>;
}




export interface IVectorMathInteraction extends IIonService
{
  Abs(leftOperand: Vector): Promise<Vector>;
  Add(leftOperand: Vector, rightOperand: Vector): Promise<Vector>;
  AndNot(leftOperand: Vector, rightOperand: Vector): Promise<Vector>;
  Clamp(leftOperand: Vector, min: Vector, max: Vector): Promise<Vector>;
  /**
   * Exercises a typedef in both argument and return position.
   */
  Component(leftOperand: Vector, index: u1): Promise<f4>;
  Do(leftOperand: Vector): Promise<VectorOfVectorOfVector>;
  /**
   * `T[]` return over a message element, beside `Spread` below.
   */
  Repeat(leftOperand: Vector, count: u1): Promise<IonArray<Vector>>;
  /**
   * `T[]?` return over a message element: `count` of 0 returns null, not an empty array.
   *
   * The null case is the one that matters — an implementation that decodes the response as a
   * single `Vector` instead of a nullable array still "works" on a non-null payload of length
   * one, so only null-vs-empty-vs-populated together pin the wire shape.
   */
  Spread(leftOperand: Vector, count: u1): Promise<IonArray<Vector> | null>;
}




