/**
 * Integer arithmetic over a fixed left-hand operand.
 *
 * The operand is supplied when the client is constructed, so calling Add(2)
 * on a client created with leftOperand = 40 yields 42.
 */
export class MathInteraction_Executor extends ServiceExecutor<IMathInteraction> implements IMathInteraction {
  constructor(public ctx: IonClientContext, private signal: AbortSignal) {
      super();
  }

  
  /**
   * Adds rightOperand to the bound operand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Add(leftOperand: i4, rightOperand: i4): Promise<i4> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Add");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.get<i4>('i4').write(writer, rightOperand);
      
    writer.writeEndArray();
          
    return await req.callAsyncT<i4>("i4", writer.data, this.signal);
  }
  /**
   * Multiplies the bound operand by rightOperand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Mul(leftOperand: i4, rightOperand: i4): Promise<i4> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Mul");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.get<i4>('i4').write(writer, rightOperand);
      
    writer.writeEndArray();
          
    return await req.callAsyncT<i4>("i4", writer.data, this.signal);
  }
  /**
   * Subtracts rightOperand from the bound operand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Sub(leftOperand: i4, rightOperand: i4): Promise<i4> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Sub");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.get<i4>('i4').write(writer, rightOperand);
      
    writer.writeEndArray();
          
    return await req.callAsyncT<i4>("i4", writer.data, this.signal);
  }
  /**
   * Divides the bound operand by rightOperand.
   *
   * Division by zero surfaces as an RPC fault, not as a return value.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Div(leftOperand: i4, rightOperand: i4): Promise<i4> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Div");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.get<i4>('i4').write(writer, rightOperand);
      
    writer.writeEndArray();
          
    return await req.callAsyncT<i4>("i4", writer.data, this.signal);
  }
  /**
   * Raises the bound operand to the power of rightOperand.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Pow(leftOperand: i4, rightOperand: i4): Promise<i4> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Pow");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.get<i4>('i4').write(writer, rightOperand);
      
    writer.writeEndArray();
          
    return await req.callAsyncT<i4>("i4", writer.data, this.signal);
  }
  /**
   * Raises the bound operand to each power in rightOperand, elementwise.
   *
   * The result array has the same length as the input array.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async PowArray(leftOperand: i4, rightOperand: IonArray<i4>): Promise<IonArray<i4>> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "PowArray");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.writeArray<i4>(writer, rightOperand, 'i4');
      
    writer.writeEndArray();
          
    return await req.callAsyncT<IonArray<i4>>("IonArray<i4>", writer.data, this.signal);
  }
  /**
   * Returns the absolute value of rightOperand, or null when it is null.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async ToPositive(leftOperand: i4, rightOperand: i4 | null): Promise<i4 | null> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "ToPositive");
          
    const writer = new CborWriter();
      
    writer.writeStartArray(2);
          
    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.writeNullable<i4>(writer, rightOperand, 'i4');
      
    writer.writeEndArray();
          
    return await req.callAsyncNullableT<i4>("i4", writer.data, this.signal);
  }
  /**
   * `i4[]?` in both argument and return position: null in, null out; otherwise the
   * elementwise power, same length as the input.
   *
   * The return is the shape the C# client used to emit `CallAsyncNullable<Array>` for —
   * `Maybe<Array<i4>>` collapsed to the bare word `Array` instead of naming the element
   * type. A value-typed element is the interesting half: `IonArray<i4>?` is a nullable
   * struct, so a reader that peels only one wrapper cannot even be coerced into compiling.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async PowArrayMaybe(leftOperand: i4, rightOperand: IonArray<i4> | null): Promise<IonArray<i4> | null> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "PowArrayMaybe");

    const writer = new CborWriter();

    writer.writeStartArray(2);

    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.writeNullableArray<i4>(writer, rightOperand, 'i4');

    writer.writeEndArray();

    return await req.callAsyncNullableArrayT<i4>("i4", writer.data, this.signal);
  }
  /**
   * The same return shape over a reference-typed element, to pin that the fix is not
   * specific to value types.
   *
   * @param leftOperand The left-hand operand shared by every method on this service.
   */
  async Spell(leftOperand: i4, rightOperand: IonArray<i4> | null): Promise<IonArray<string> | null> {
    const req = new IonRequest(this.ctx, "IMathInteraction", "Spell");

    const writer = new CborWriter();

    writer.writeStartArray(2);

    IonFormatterStorage.get<i4>('i4').write(writer, leftOperand);
    IonFormatterStorage.writeNullableArray<i4>(writer, rightOperand, 'i4');

    writer.writeEndArray();

    return await req.callAsyncNullableArrayT<string>("string", writer.data, this.signal);
  }

}

