/**
 * Deterministic pseudo-random streams seeded by the caller.
 */
export class RandomStreamInteraction_Executor extends ServiceExecutor<IRandomStreamInteraction> implements IRandomStreamInteraction {
  constructor(public ctx: IonClientContext, private signal: AbortSignal) {
      super();
  }

  
  /**
   * Streams i pseudo-random integers derived from the seed.
   *
   * @param seed Seed for the underlying generator. The same seed always yields the
   *   same sequence, which is what makes the streaming tests reproducible.
   */
  Integer(seed: i4, i: i4): AsyncIterable<i4> {
    const ws = new IonWsClient(this.ctx, "IRandomStreamInteraction", "Integer");
    
    const writer = new CborWriter();
    
    writer.writeStartArray(2);
    
    IonFormatterStorage.get<i4>('i4').write(writer, seed);
    IonFormatterStorage.get<i4>('i4').write(writer, i);
    
    writer.writeEndArray();
    
    return ws.callServerStreaming<i4>("i4", writer.data, this.signal);
  }
  /**
   * Bidirectional stream: every f4 pushed by the client is answered with a
   * pseudo-random f4 derived from the seed and that input.
   *
   * @param seed Seed for the underlying generator. The same seed always yields the
   *   same sequence, which is what makes the streaming tests reproducible.
   */
  Floats(seed: i4, inputStream: AsyncIterable<f4>): AsyncIterable<f4> {
    const ws = new IonWsClient(this.ctx, "IRandomStreamInteraction", "Floats");
    
    const writer = new CborWriter();
    
    writer.writeStartArray(1);
    
    IonFormatterStorage.get<i4>('i4').write(writer, seed);
    
    writer.writeEndArray();
    
    return ws.callServerStreamingFullDuplex<f4, f4>("f4", writer.data, inputStream, "f4", this.signal);
  }

}

IonFormatterStorage.registerClientExecutor<IRandomStreamInteraction>('RandomStreamInteraction', RandomStreamInteraction_Executor);

